	/** 바닥 먹이의 시간을 흘려보낸다. 오래 둔 고기·프로틴은 상한 먹이가 된다 (재고도 상한 먹이로 옮긴다). */
	function ageFloorFood(save, foods, minutes = 1) {
		let next = save, spoiled = 0;
		const out = foods.map((f) => {
			if (f.kind === "rotten") return f;
			const age = (f.age ?? 0) + minutes;
			if (age < 2880 || next[STOCK[f.kind]] <= 0) return {
				...f,
				age
			};
			spoiled += 1;
			const units = Math.min(foodUnits(f), next[STOCK[f.kind]]);
			next = {
				...next,
				[STOCK[f.kind]]: next[STOCK[f.kind]] - units,
				rotten: next.rotten + 1
			};
			const { remaining, age: oldAge, gift, ...placed } = f;
			return {
				...placed,
				kind: "rotten"
			};
		});
		return {
			save: next,
			foods: out,
			spoiled
		};
	}
